\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$ begin begin execute command;exception when others then raise notice 'PASS denied: %',label;return;end;raise exception 'FAIL allowed: %',label;end $$;
select pg_temp.assert_true((select count(*)=114 from observation_catalog_types where version=2),'v2 catalog available without changing v1');
select pg_temp.assert_true((select count(*)=101 from observation_catalog_types where version=1),'v1 catalog preserved');
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002'),('00000000-0000-0000-0000-000000000003');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
with made as (insert into observations(author_id,category,title,description,latitude,longitude,taxonomy_version,domain_id,topic_id,event_type_id,answers,extent) values(auth.uid(),'Safety','Snow surface fixture','',61.2181,-149.9003,2,'weather','weather.winter','snow_surface','{"snow_surface":"powder"}','{"type":"Polygon","coordinates":[[[-149.9,61.218],[-149.89,61.218],[-149.89,61.23],[-149.9,61.218]]]}') returning id) select set_config('test.observation',(select id::text from made),true);
select pg_temp.assert_true((select description='' from observations),'sharing does not require typing');
select pg_temp.assert_true((select expires_at=observed_at+interval '24 hours' from observations),'expiry anchored to observed time');
select pg_temp.assert_true((select extent->'coordinates'->0->0='[-149.90,61.22]'::jsonb from observations),'extent rounded before persistence');
select pg_temp.assert_true((select count(*)=1 from observations_in_bounds(-149.891,61.229,-149.889,61.231)),'spatial lookup finds an area even outside its anchor point');
select pg_temp.denied($q$update observations set expires_at=now()+interval '1 year'$q$,'clients cannot extend expiry');
select pg_temp.denied($q$select respond_to_observation(current_setting('test.observation')::uuid,'observed',now())$q$,'author cannot claim independent confirmation');
select pg_temp.denied($q$update observations set extent='{"type":"Polygon","coordinates":[[[0,0],[1,0],[1,1],[0,0]]]}'$q$,'unrelated extent rejected');
select pg_temp.denied($q$update observations set extent='{"type":"Polygon","coordinates":[[[-149.90,61.22],[-149.89,61.23],[-149.90,61.23],[-149.89,61.22],[-149.90,61.22]]]}'$q$,'self-crossing area rejected');
insert into followed_places(name,latitude,longitude) values('Synthetic saved place',61.22,-149.9);
select pg_temp.assert_true((select count(*)=1 from followed_places),'owner sees followed place');
select pg_temp.denied($q$insert into followed_places(user_id,name,latitude,longitude) values('00000000-0000-0000-0000-000000000002','Spoof',61,-149)$q$,'cannot follow as another account');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from followed_places),'other account cannot read followed place');
select respond_to_observation(current_setting('test.observation')::uuid,'observed',now());
select pg_temp.assert_true((select count(*)=1 from observation_responses),'responder reads own response');
select pg_temp.denied($q$select respond_to_observation(current_setting('test.observation')::uuid,'changed',now())$q$,'response rate limit');
select pg_temp.denied($q$insert into observation_responses(observation_id,user_id,response,observed_at) values(current_setting('test.observation')::uuid,auth.uid(),'observed',now())$q$,'direct response writes denied');
select pg_temp.denied($q$select respond_to_observation(current_setting('test.observation')::uuid,'observed',now()+interval '1 day')$q$,'future firsthand time rejected');
reset role;
update observation_responses set recorded_at=clock_timestamp()-interval '1 minute';
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select respond_to_observation(current_setting('test.observation')::uuid,'changed',now());
select pg_temp.assert_true((select count(*)=1 from observation_responses),'one current response per user');
select pg_temp.assert_true((select expires_at=observed_at+interval '24 hours' from observations),'confirmation does not extend original expiry');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_true((select count(*)=0 from observation_responses),'author cannot see responder identity');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((observation_response_summary(current_setting('test.observation')::uuid)->>'changed')::integer=1,'anonymous sees aggregate changed count only');
select pg_temp.denied($q$select * from observation_responses$q$,'anonymous cannot read individual responses');
select pg_temp.denied($q$select * from followed_places$q$,'anonymous cannot read followed places');
select pg_temp.denied($q$select * from my_observations()$q$,'anonymous owner RPC execution revoked');
select pg_temp.denied($q$select * from staff_review_queue()$q$,'anonymous staff RPC execution revoked');
select pg_temp.denied($q$select respond_to_observation(current_setting('test.observation')::uuid,'observed',now())$q$,'anonymous response RPC execution revoked');
reset role;
-- A normal text edit must not renew an old condition.
update observations set observed_at=now()-interval '2 days' where id=current_setting('test.observation')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
update observations set title='Edited snow fixture';
select pg_temp.assert_true((select expires_at=observed_at+interval '24 hours' and expires_at<now() from observations),'text edit preserves expiry');
select pg_temp.assert_true((select count(*)=1 from my_observations()),'owner history retains outdated observation');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((select count(*)=0 from observations_in_bounds(-150,61,-149,62)),'expired observation absent from active spatial API');
select pg_temp.assert_true((select count(*)=1 from observation_feed),'history retains public record without all-clear inference');
reset role;

select pg_temp.denied($q$select catalog_policy(2,'outdoors','outdoors.ice','ice_climbing','{}','{"grade":"WI4","grade_system":"wi","grade_basis":"published"}')$q$,'published climbing grade requires reference');
select pg_temp.denied($q$select catalog_policy(2,'outdoors','outdoors.ice','ice_climbing','{}','{"grade":"M5","grade_system":"wi","grade_basis":"estimate"}')$q$,'grade cannot mix difficulty scales');
select pg_temp.assert_true((catalog_policy(2,'outdoors','outdoors.ice','ice_climbing','{}','{"grade":"WI4","grade_system":"wi","grade_basis":"published","route_reference":"Synthetic guide page 12"}')->>'privacy')='approximate','attributed grade remains an observation not staff risk');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$insert into followed_places(name,latitude,longitude) select 'Synthetic '||i,60+i*0.01,-149 from generate_series(1,50) i$q$,'followed places capped at fifty');
select pg_temp.assert_true((select count(*)=1 from followed_places),'failed bulk follow is atomic');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
insert into report_flags(observation_id,reporter_id,reason) values(current_setting('test.observation')::uuid,auth.uid(),'privacy');
select pg_temp.denied($q$select * from staff_flag_queue()$q$,'ordinary account cannot access flag queue');
select pg_temp.denied($q$select resolve_report_flags(current_setting('test.observation')::uuid,'No staff authority')$q$,'ordinary account cannot resolve flags');
reset role;
insert into moderators values('00000000-0000-0000-0000-000000000003');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select pg_temp.assert_true((select count(*)=1 from staff_flag_queue()),'staff sees flagged observations');
select resolve_report_flags(current_setting('test.observation')::uuid,'Synthetic privacy review completed');
select pg_temp.assert_true((select count(*)=0 from staff_flag_queue()),'resolved flags leave active queue');
select pg_temp.assert_true((select count(*)=1 from moderation_actions where reason like 'Flags resolved:%'),'flag decision audited');
select pg_temp.assert_true(not has_column_privilege('authenticated','report_flags','resolved_by','select'),'staff identity not exposed through flag table grants');
reset role;

set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
insert into observations(author_id,category,title,description,latitude,longitude,taxonomy_version,domain_id,topic_id,event_type_id,extent) values(auth.uid(),'Outdoors','Synthetic carcass','',61.2181,-149.9003,2,'wildlife','wildlife.signs','carcass','{"type":"Polygon","coordinates":[[[0,0],[1,0],[1,1],[0,0]]]}');
select pg_temp.assert_true((select extent is null and latitude=61.2 from observations where event_type_id='carcass'),'sensitive wildlife extent discarded before persistence');
insert into observations(author_id,category,title,description,latitude,longitude,taxonomy_version,domain_id,topic_id,event_type_id,extent) values(auth.uid(),'Travel','Synthetic collision','',61.2181,-149.9003,2,'travel','travel.vehicle','collision','{"type":"LineString","context":"official_closure","coordinates":[[-149.9,61.22],[-149.88,61.24]]}');
select pg_temp.assert_true((select extent->>'context'='traffic_backup' from observations where event_type_id='collision'),'collision stretch is traffic backup, never an official closure');
reset role;
rollback;
